// NG2
import { DestroyRef, Directive, Input, TemplateRef, ViewContainerRef } from '@angular/core';
// App
import { Security } from 'novo-elements/services';

@Directive({
    selector: '[bhUnless]',
    standalone: false,
})
export class Unless {
  permissions: string = '';
  isDisplayed: boolean = false;

  constructor(
    public templateRef: TemplateRef<any>,
    public viewContainer: ViewContainerRef,
    public security: Security,
    private destroyRef: DestroyRef) {
    const sub = this.security.subscribe(this.check.bind(this));
    this.destroyRef.onDestroy(() => {
      // If Security uses an old definition, subscribe will return void/undefined.
      try {
        sub?.unsubscribe();
      } catch {}
    });
  }

  @Input()
  set bhUnless(value: string) {
    this.permissions = value || '';
    this.check();
  }

  check(): void {
    let display: boolean = false;
    if (~this.permissions.indexOf('||')) {
      const ps: any = this.permissions.split('||');
      for (const p of ps) {
        if (this.security.has(p.trim())) {
          display = true;
        }
      }
    } else {
      display = this.permissions.split('&&').every((p) => this.security.has(p.trim()));
    }

    if (display) {
      if (!this.isDisplayed) {
        this.isDisplayed = true;
        this.viewContainer.createEmbeddedView(this.templateRef);
      }
    } else {
      this.isDisplayed = false;
      this.viewContainer.clear();
    }
  }
}
